package dk.sdu.cbse.gamelab; import java.util.*; public final class CollisionComponent implements IPostEntityProcessingService{public void process(GameData d,double dt){List<Entity> copy=new ArrayList<>(d.entities);Set<Entity> remove=new HashSet<>(),add=new HashSet<>();for(Entity bullet:copy.stream().filter(e->e.type.equals("BULLET")).toList())for(Entity target:copy){if(target==bullet||target.type.equals("BULLET")||target.type.equals(bullet.owner))continue;double dx=bullet.x-target.x,dy=bullet.y-target.y;if(Math.sqrt(dx*dx+dy*dy)<=bullet.radius+target.radius){remove.add(bullet);if(target.type.equals("ASTEROID")){remove.add(target);if(target.radius>18){for(int i=-1;i<=1;i+=2){Entity a=new Entity("ASTEROID",target.x,target.y,target.radius/2);a.dx=target.dy*i;a.dy=-target.dx*i;add.add(a);}}}else if(--target.health<=0)remove.add(target);}}for(Entity ship:copy.stream().filter(e->e.type.equals("PLAYER")||e.type.equals("ENEMY")).toList())for(Entity a:copy.stream().filter(e->e.type.equals("ASTEROID")).toList()){double dx=ship.x-a.x,dy=ship.y-a.y;if(Math.sqrt(dx*dx+dy*dy)<=ship.radius+a.radius)remove.add(ship);}d.entities.removeAll(remove);d.entities.addAll(add);}}